import { PunchType } from '@recafco/db';
import {
  IsEnum,
  IsISO8601,
  IsNotEmpty,
  IsNumber,
  IsObject,
  IsOptional,
  IsString,
  IsUUID,
  Max,
  MaxLength,
  Min,
} from 'class-validator';

/**
 * TIME-01 contract. The official punch instant is ALWAYS generated by the server at receipt —
 * no field in this DTO can set or move it. Client clock values are diagnostic only.
 */
export class CreateMobilePunchDto {
  @IsEnum(PunchType)
  punchType!: PunchType;

  /**
   * Diagnostic only: the phone's clock at the moment of the tap (ISO-8601). Stored as
   * `clientReportedTime` and compared with the server receipt time to flag clock drift.
   * Never used for validation, duplicate detection, workDate or calculation.
   */
  @IsOptional()
  @IsISO8601()
  clientReportedTime?: string;

  /**
   * DEPRECATED (pre-TIME-01 APKs): previously the official punch time. Still accepted so that
   * already-installed apps keep working, but it is now treated exactly like `clientReportedTime`
   * (diagnostic only). New clients must not send it.
   */
  @IsOptional()
  @IsISO8601()
  punchTimeSource?: string;

  /**
   * Client-generated UUID identifying one intentional punch action. A retry of the same action
   * must reuse it; a new tap must generate a new one. Optional only for pre-TIME-01 APKs.
   */
  @IsOptional()
  @IsUUID()
  clientRequestId?: string;

  @IsOptional()
  @IsNumber()
  @Min(-90)
  @Max(90)
  latitude?: number;

  @IsOptional()
  @IsNumber()
  @Min(-180)
  @Max(180)
  longitude?: number;

  @IsOptional()
  @IsNumber()
  @Min(0)
  gpsAccuracy?: number;

  @IsOptional()
  @IsString()
  workLocationId?: string;

  @IsString()
  @IsNotEmpty()
  @MaxLength(255)
  deviceIdentifier!: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  wifiSsid?: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  wifiBssid?: string;

  @IsOptional()
  @IsString()
  @MaxLength(50)
  appVersion?: string;

  @IsOptional()
  @IsObject()
  fraudSignals?: Record<string, unknown>;

  @IsOptional()
  @IsString()
  @MaxLength(255)
  selfieFileId?: string;
}
